{"command":"python - <<'PY'
import sqlite3
for name in ('source.db', 'target.db'):
    path = '/testbed/migration-recon/databases/' + name
    con = sqlite3.connect('file:' + path + '?mode=ro', uri=True)
    try:
        tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        print(name, 'orders_archive present:', 'orders_archive' in tables)
        if 'orders_archive' in tables:
            print('orders_archive rows:', con.execute('SELECT COUNT(*) FROM orders_archive;').fetchone()[0])
    finally:
        con.close()
PY","timeout":30}

